//! 🧵️ Same-bank bulk cursor actions retain their real producer, reply and output.
use super::*;
use semio_framework_value_control_contract::{OriginalSourceTurnIdentity,OriginalEffectInvocationIdentity,RetainedAllocationEffect,OriginalEffectReply,OriginalEffectReplyComplete,OriginalEffectCallbackMode,OriginalEffectProducer,OriginalEffectAuthority,OriginalEffectAction,RetainedWorkPoll,RetainedWorkOutcome};
use semio_framework_value_retirement::OriginalRetirementFailure;

use semio_framework_value_clone_source_testing::FixtureSource;
use semio_framework_value_retirement::forward_original_value_reply;
use super::observe;
use std::mem::ManuallyDrop;

#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub(crate) enum Op{Advance,Take,Start,Close,BoundClose,OutputStart,OutputClose}
type Key=(OriginalEffectInvocationIdentity,Op,usize,u64,(u64,usize,usize,usize));
struct Context<'a,T:RetainedClone>{source:RetainedCloneRef<'a,T>,turn:OriginalSourceTurnIdentity,op:Op,body:usize,maximum:u64}
struct Producer<T:RetainedClone>{cursor:ManuallyDrop<T::Cursor>,output:ManuallyDrop<Option<T>>,output_close:ManuallyDrop<RetainedCloneClose>,take_reply:ManuallyDrop<Option<Result<RetainedCloneStep,ValueError>>>,selection:Option<Key>,source:(u64,usize,usize,usize)}
impl<T:RetainedClone> Producer<T>{fn empty(&self)->bool{self.cursor.native_terminal_release().is_some_and(|witness|witness.validates(&*self.cursor))&&self.output.is_none()&&self.output_close.is_empty()&&self.take_reply.is_none()&&self.selection.is_none()}
 fn dispatch<'r>(&mut self,context:&mut Context<'_,T>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>,recover:bool)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{let invocation=effect.invocation().ok_or_else(||ValueError::invariant("bulk fixture action lacks its original invocation"))?;let mode=if recover{OriginalEffectCallbackMode::Recover}else{OriginalEffectCallbackMode::Receive};if invocation.mode()!=mode{return Err(ValueError::invariant("bulk fixture changed its invocation mode"))}let key=(invocation.identity(),context.op,context.body,context.maximum,context.source.reference_identity());if self.take_reply.is_some()&&(!recover||context.op!=Op::Take){return Err(ValueError::invariant("bulk fixture retained another take reply"))}if recover{if self.selection!=Some(key){return Err(ValueError::invariant("bulk fixture changed its selected action"))}}else if self.selection.is_some(){return Err(ValueError::invariant("bulk fixture still owns its selected action"))}if !recover&&context.op==Op::Close&&!self.cursor.terminal_is_empty(){let demand=self.cursor.close_demands(context.body)?;let work=self.cursor.close_work_demand(context.body)?;if !retained_clone_grant_admits(effect.grant(),demand)||effect.remaining_work_units()?<work{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}}let mut scope=reply.scope(&mut self.selection,key)?;let done=match context.op{Op::Advance=>if recover{self.cursor.recover_advance_into(context.source,context.body,context.maximum,effect,scope.borrow()?)?}else{self.cursor.advance_into(context.source,context.body,context.maximum,effect,scope.borrow()?)?},Op::Take=>{if self.take_reply.is_none(){let inner=OriginalEffectReply::borrow(&mut *self.take_reply)?;let result=if recover{self.cursor.recover_take(&mut *self.output,effect,inner)?}else{self.cursor.take(&mut *self.output,effect,inner)?};drop(result)}forward_original_value_reply(&mut *self.take_reply,scope.borrow()?)?},Op::Start=>if recover{self.cursor.recover_begin_close_into(effect,scope.borrow()?)?}else{self.cursor.begin_close_into(effect,scope.borrow()?)?},Op::Close=>if recover{self.cursor.recover_close_into(context.body,effect,scope.borrow()?)?}else{self.cursor.close_into(context.body,effect,scope.borrow()?)?},Op::BoundClose=>if recover{self.cursor.recover_close_bound_into(context.source,context.body,effect,scope.borrow()?)?}else{self.cursor.close_bound_into(context.source,context.body,effect,scope.borrow()?)?},Op::OutputStart=>{if recover{return Err(ValueError::invariant("native output close-start cannot be replayed"))}let turn=self.output_close.begin_granted(&mut *self.output,effect);scope.borrow()?.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into))},Op::OutputClose=>if recover{self.output_close.recover_step_into(context.body,effect,scope.borrow()?)?}else{self.output_close.step_into(context.body,effect,scope.borrow()?)?}};drop(done);Ok(scope.forwarded())}
}
impl<T:RetainedClone> Drop for Producer<T>{fn drop(&mut self){let empty=self.empty();assert!(std::thread::panicking()||empty,"bulk fixture producer retains its original cursor or output");if empty{unsafe{ManuallyDrop::drop(&mut self.cursor);ManuallyDrop::drop(&mut self.output);ManuallyDrop::drop(&mut self.output_close);ManuallyDrop::drop(&mut self.take_reply)}}}}
impl<T:RetainedClone> OriginalEffectProducer for Producer<T>{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Context<'a,T> where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.source.reference_identity()!=self.source{return Err(ValueError::invariant("bulk fixture original Source changed"))}Ok(())}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.turn)}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,effect,reply,false)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,effect,reply,true)}}

pub(crate) struct Harness<T:RetainedClone>{authority:ManuallyDrop<Option<OriginalEffectAuthority<Producer<T>>>>,action:ManuallyDrop<Option<OriginalEffectAction<RetainedCloneStep,OriginalRetirementFailure>>>,reply:ManuallyDrop<Option<Result<RetainedCloneStep,OriginalRetirementFailure>>>,context_error:ManuallyDrop<Option<ValueError>>,producer:ManuallyDrop<Option<Producer<T>>>}
impl<T:RetainedClone> Harness<T>{
 pub(crate) fn new(source:&FixtureSource<T>)->Self{Self{authority:ManuallyDrop::new(Some(OriginalEffectAuthority::new(Producer{cursor:ManuallyDrop::new(T::retained_clone_cursor()),output:ManuallyDrop::new(None),output_close:ManuallyDrop::new(Default::default()),take_reply:ManuallyDrop::new(None),selection:None,source:source.borrow().reference_identity()}))),action:ManuallyDrop::new(None),reply:ManuallyDrop::new(None),context_error:ManuallyDrop::new(None),producer:ManuallyDrop::new(None)}}
 pub(crate) fn ready(&self)->bool{self.authority.as_ref().unwrap().inspect(|p|p.cursor.output_ready())}
 pub(crate) fn terminal(&self)->bool{self.authority.as_ref().unwrap().inspect(|p|p.cursor.terminal_is_empty())}
 pub(crate) fn inspect_output<R>(&self,query:impl FnOnce(Option<&T>)->R)->R{self.authority.as_ref().unwrap().inspect(|p|query((&*p.output).as_ref()))}
 pub(crate) fn inspect_cursor<R>(&self,query:impl FnOnce(&T::Cursor)->R)->R{self.authority.as_ref().unwrap().inspect(|p|query(&*p.cursor))}
 pub(crate) fn has_output(&self)->bool{self.authority.as_ref().unwrap().inspect(|p|p.output.is_some())}
 pub(crate) fn output_close_empty(&self)->bool{self.authority.as_ref().unwrap().inspect(|p|p.output_close.is_empty())}
 pub(crate) fn quote(&self,source:&FixtureSource<T>,op:Op,body:usize,maximum:u64)->(RetirementDemand,u64){let original=source.borrow();self.authority.as_ref().unwrap().inspect(|p|match op{Op::Advance=>{let selected=p.cursor.advance_selection(original,body,maximum).unwrap();(selected.demand(),selected.work())},Op::Take=>(p.cursor.take_demand().unwrap(),p.cursor.take_work_demand().unwrap()),Op::Start=>(p.cursor.begin_close_demand().unwrap(),p.cursor.begin_close_work_demand().unwrap()),Op::Close=>(p.cursor.close_demands(body).unwrap(),p.cursor.close_work_demand(body).unwrap()),Op::BoundClose=>(p.cursor.close_bound_demands(original,body).unwrap(),p.cursor.close_bound_work_demand(original,body).unwrap()),Op::OutputStart|Op::OutputClose=>(p.output_close.next_owner_demands::<T>(p.output.is_some(),&None,body).unwrap(),p.output_close.next_owner_work::<T>(p.output.is_some(),&None,body).unwrap())})}
 pub(crate) fn drive(&mut self,source:&mut FixtureSource<T>,op:Op,body:usize,maximum:u64,grant:RetainedCloneGrant,units:u64)->(RetainedCloneStep,(usize,usize)){let mut heap=(0usize,0usize);for _ in 0..100000{let completed=source.with_bank(|original,bank|{let ((poll,actual),observed)=observe(||bank.run_with_source(grant,units,|effect,turn|{let before=effect.performed_work();let mut context=Context{source:original,turn:turn.identity(),op,body,maximum};let result=self.authority.as_mut().unwrap().drive(&mut context,effect,&mut *self.action);let work=effect.performed_work()-before;match result{Ok(true)=>RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work}),Ok(false)=>RetainedWorkPoll::Pending{work},Err(error)=>{*self.context_error=Some(error);RetainedWorkPoll::Pending{work}}}}));heap.0=heap.0.checked_add(observed.0).unwrap();heap.1=heap.1.checked_add(observed.1).unwrap();if let Some(actual)=actual{assert_eq!(actual,heap.0)}if self.context_error.is_some(){panic!("bulk original action retained an orchestration failure: {:?}",self.context_error.as_ref())}let RetainedWorkPoll::Complete(turn)=poll else{return None};turn.result.unwrap();assert!(self.action.as_mut().unwrap().transfer_reply(&mut *self.reply).unwrap());self.authority.as_mut().unwrap().finish(&mut *self.action).unwrap();let progress=match self.reply.as_ref().unwrap(){Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};assert_ne!(bank.take_admitted(),Some(false));assert!(progress.fits(bank.wallet().remaining()),"actual progress {progress:?} exceeds finite Source stock {:?}",bank.wallet().remaining());bank.post(progress,grant,heap);let step=match self.reply.as_ref().unwrap(){Ok(step)=>*step,Err(_)=>panic!("String original cursor retained a failure")};self.reply.take();Some(step)}).unwrap();if let Some(step)=completed{return(step,heap)}}panic!("String original action remained pending")}
 pub(crate) fn release(&mut self,source:&mut FixtureSource<T>){assert!(self.authority.as_ref().unwrap().inspect(Producer::empty));let demand=OriginalEffectAuthority::<Producer<T>>::producer_transfer_demand().unwrap();source.with_bank(|original,bank|{let grant=bank.loan(1,demand.copy_bytes);let ((poll,actual),heap)=observe(||bank.run_with_source(grant,1,|effect,turn|{let context=Context{source:original,turn:turn.identity(),op:Op::Close,body:0,maximum:0};let turn=OriginalEffectAuthority::transfer_producer(&mut *self.authority,&context,&mut *self.producer,effect);RetainedWorkPoll::Complete(turn)}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("String producer transfer pending")};let progress=turn.result.unwrap().unwrap();if let Some(actual)=actual{assert_eq!(actual,heap.0)}assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,heap);let witness=unsafe{RetainedCursorRelease::native(Producer::empty)};assert!(witness.validates(self.producer.as_ref().unwrap()));let demand=witness.inline_demand();let grant=bank.loan(1,demand.copy_bytes);let mut reply=None;let ((poll,actual),heap)=observe(||bank.run(grant,witness.inline_work(),|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut reply).unwrap();drop(witness.inline_into(&mut *self.producer,effect,token).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("String producer release pending")};turn.result.unwrap();let step=reply.take().unwrap().unwrap();if let Some(actual)=actual{assert_eq!(actual,heap.0)}assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(step.progress(),grant,heap);}).unwrap();assert!(self.producer.is_none());}
}
impl<T:RetainedClone> Drop for Harness<T>{fn drop(&mut self){let empty=self.authority.is_none()&&self.action.is_none()&&self.reply.is_none()&&self.context_error.is_none()&&self.producer.is_none();assert!(std::thread::panicking()||empty,"bulk fixture retains its original producer");if empty{unsafe{ManuallyDrop::drop(&mut self.authority);ManuallyDrop::drop(&mut self.action);ManuallyDrop::drop(&mut self.reply);ManuallyDrop::drop(&mut self.context_error);ManuallyDrop::drop(&mut self.producer)}}}}

impl Harness<String>{pub(crate) fn output_matches(&self,text:&str)->bool{self.inspect_output(|output|output.is_some_and(|value|value==text))}}
